struction.archive l ON l.dateTime=t.left_time LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=t.right_time LEFT JOIN loucka_reconstruction.archive current_row ON current_row.dateTime=t.target_time WHERE current_row.dateTime IS NULL
